#!/usr/bin/env bash
# Final pre-submission hardening:
#   1) scripts/ntc_primary_stats.py   — AUCC with error bars + paired sign /
#      Wilcoxon tests across settings (closes the "no variability, no
#      significance" objection on the headline table)
#   2) scripts/ntc_v2_diagnostic.py   — quantifies whether the medium tier
#      binds at all (identical NTC-v2 / AGREE rows)
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing final hardening scripts..."
decode "scripts/ntc_primary_stats.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_v2_diagnostic.py" << 'B64EOF'

B64EOF
echo ""
echo "Installed. Run the primary stats (this is the headline table) and the diagnostic."